// Structure interview questions
const aiResponse = $json.message.content;
let questionsData;

try {
  const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
  questionsData = jsonMatch ? JSON.parse(jsonMatch[0]) : { categories: {} };
} catch (e) {
  questionsData = { categories: {}, error: 'Failed to parse' };
}

// Add metadata
questionsData.role = $json.body.role;
questionsData.company = $json.body.company;
questionsData.generated_at = new Date().toISOString();
questionsData.source = 'ai_powered';

return {
  json: questionsData
};
